// Package cve matches service fingerprints (CPE + version) against a CVE
// dataset committed to the repo (architecture D11, §11). Everything here is
// offline: the data is regenerated by `make cve-db` on a dev machine and
// embedded into the binary; the build and the runtime never call out.
package cve

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"
	"sync"
)

//go:embed products.txt
var productsTxt []byte

//go:embed data/cve.json.gz
var dataGz []byte

// DataFile is the generated dataset, relative to this package's directory.
const DataFile = "data/cve.json.gz"

// Product is one line of products.txt.
type Product struct {
	Name    string   // display name, e.g. "Apache httpd"
	NVD     []string // vendor:product names fetched from NVD
	Aliases []string // other vendor:product names scanners report for it
}

// ParseProducts reads the products.txt format (see the file's header).
func ParseProducts(b []byte) ([]Product, error) {
	var out []Product
	sc := bufio.NewScanner(bytes.NewReader(b))
	for n := 1; sc.Scan(); n++ {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		name, rest, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("products.txt:%d: missing '='", n)
		}
		nvd, alias, _ := strings.Cut(rest, "|")
		p := Product{Name: strings.TrimSpace(name), NVD: strings.Fields(nvd), Aliases: strings.Fields(alias)}
		if p.Name == "" || len(p.NVD) == 0 {
			return nil, fmt.Errorf("products.txt:%d: need a name and at least one NVD vendor:product", n)
		}
		for _, c := range append(append([]string{}, p.NVD...), p.Aliases...) {
			if strings.Count(c, ":") != 1 {
				return nil, fmt.Errorf("products.txt:%d: %q is not vendor:product", n, c)
			}
		}
		out = append(out, p)
	}
	return out, sc.Err()
}

// Products returns the embedded curated list.
func Products() []Product {
	p, err := ParseProducts(productsTxt)
	if err != nil {
		panic(err) // the embedded file is covered by a test
	}
	return p
}

// DB is the committed dataset (data/cve.json.gz).
type DB struct {
	Generated string              `json:"generated"` // RFC 3339, when `make cve-db` ran
	CVEs      map[string]Record   `json:"cves"`      // by CVE id
	Products  map[string][]Affect `json:"products"`  // by NVD vendor:product
}

// Record holds the facts of one CVE we show and score by.
type Record struct {
	CVSS      float64 `json:"s,omitempty"`    // CVSS v3.x (or v4/v2 fallback) base score
	Severity  string  `json:"sev,omitempty"`  // NVD base severity, e.g. "HIGH"
	Published string  `json:"pub,omitempty"`  // YYYY-MM-DD
	KEV       bool    `json:"kev,omitempty"`  // in CISA Known Exploited Vulnerabilities
	EPSS      float64 `json:"epss,omitempty"` // FIRST EPSS probability 0..1
}

// Affect says which versions of a product one CVE applies to.
type Affect struct {
	ID     string  `json:"id"`
	Ranges []Range `json:"r"`
}

// Range is one NVD cpeMatch: either an exact version or bounds. A Range
// with no fields is never stored (NVD "all versions" entries are skipped).
type Range struct {
	Exact     string `json:"v,omitempty"`
	StartIncl string `json:"si,omitempty"`
	StartExcl string `json:"se,omitempty"`
	EndIncl   string `json:"ei,omitempty"`
	EndExcl   string `json:"ee,omitempty"`
}

// Decode reads a gzip'd JSON dataset.
func Decode(gz []byte) (*DB, error) {
	r, err := gzip.NewReader(bytes.NewReader(gz))
	if err != nil {
		return nil, fmt.Errorf("cve data: %w", err)
	}
	defer r.Close()
	var db DB
	if err := json.NewDecoder(r).Decode(&db); err != nil {
		return nil, fmt.Errorf("cve data: %w", err)
	}
	return &db, nil
}

var (
	loadOnce sync.Once
	loaded   *DB
	loadErr  error
)

// Load returns the embedded dataset, decoded once.
func Load() (*DB, error) {
	loadOnce.Do(func() { loaded, loadErr = Decode(dataGz) })
	return loaded, loadErr
}
